// --- Lightning / Flash ---
// Random bright white flash with afterglow
var _lightningTimer = 0;
var _lightningPos = 0;
var _lightningRecharge = 0;
var _lightningBursts = 0;
var _lightningWidth = 1;

// 中文：闪电效果，随机白光爆闪并带微弱余辉
function effectLightning(frequency) {
    var count = getLedCount();
    frequency = clamp(frequency, 1, 30);
    if (_lightningRecharge > 0) { _lightningRecharge = _lightningRecharge - 1; }
    if (_lightningTimer <= 0) {
        if (_lightningBursts > 0) {
            _lightningTimer = 1 + random(2);
            _lightningBursts = _lightningBursts - 1;
            _lightningPos = clamp(_lightningPos + random(5) - 2, 0, count - 1);
            _lightningWidth = 1 + random(3);
        } else if (_lightningRecharge == 0 && random(100) < frequency) {
            _lightningTimer = 2 + random(2);
            _lightningBursts = 1 + random(2);
            _lightningPos = random(count);
            _lightningWidth = 1 + random(2);
            _lightningRecharge = 8 + random(16);
        }
    }

    var ambient = 2 + ((sin255((_frame * 3) % 256) + 255) * 2) / 255;
    var i = 0;
    while (i < count) {
        led(i, ambient / 2, ambient / 2, ambient);
        i = i + 1;
    }

    if (_lightningTimer > 0) {
        var bright = 150 + _lightningTimer * 45;
        i = _lightningPos - (_lightningWidth + 1);
        if (i < 0) { i = 0; }
        while (i <= _lightningPos + _lightningWidth + 1 && i < count) {
            var dist = abs(i - _lightningPos);
            var falloff = 255 - (dist * 180 / (_lightningWidth + 1));
            if (falloff < 0) { falloff = 0; }
            var v = (bright * falloff) / 255;
            if (v > 255) { v = 255; }
            led(i, v, v, clamp((v * 220) / 255, 0, 255));
            i = i + 1;
        }
        _lightningTimer = _lightningTimer - 1;
    }
}

// --- Pulse (expanding from center) ---
// Radiates outward from center, with color
// 中文：脉冲扩散，从中心向两侧推出一圈亮带
function effectPulse(r, g, b, speed) {
    var count = getLedCount();
    if (count < 1) { return; }
    speed = _atLeastOne(speed);
    var center = (count - 1) / 2;
    var maxDist = center + 1;
    var cycleFrames = speed * (count + 6);
    if (cycleFrames < 24) { cycleFrames = 24; }
    var waveFront = (_positiveMod(_frame, cycleFrames) * (maxDist + 1.5)) / cycleFrames;
    var i = 0;
    while (i < count) {
        var dist = abs(i - center);
        var diff = abs(dist - waveFront);
        var bright = 255 - diff * 170;
        if (waveFront < 0.8) {
            bright = bright + (0.8 - waveFront) * 80;
        }
        if (bright < 0) { bright = 0; }
        led(i, (r * bright) / 255, (g * bright) / 255, (b * bright) / 255);
        i = i + 1;
    }
}

// A single center-origin wavefront. Unlike effectPulse/effectRipple, this does
// not loop inside the clip, so storyboard direction remains unambiguous.
function effectCenterExpand(r, g, b, duration, width) {
    var count = getLedCount();
    if (count < 1) { return; }
    duration = _atLeastOne(duration);
    width = _atLeastOne(width);
    var center = (count - 1) / 2;
    var maxDist = center + 0.5;
    var progress = clamp(_frame / duration, 0, 1);
    var front = progress * maxDist;
    var i = 0;
    while (i < count) {
        var dist = abs(i - center);
        var bright = 255 - (abs(dist - front) * 255) / width;
        if (bright < 0) { bright = 0; }
        led(i, (r * bright) / 255, (g * bright) / 255, (b * bright) / 255);
        i = i + 1;
    }
}

// A single wavefront travelling from both ends back toward the center.
function effectCenterContract(r, g, b, duration, width) {
    var count = getLedCount();
    if (count < 1) { return; }
    duration = _atLeastOne(duration);
    width = _atLeastOne(width);
    var center = (count - 1) / 2;
    var maxDist = center + 0.5;
    var progress = clamp(_frame / duration, 0, 1);
    var front = (1 - progress) * maxDist;
    var i = 0;
    while (i < count) {
        var dist = abs(i - center);
        var bright = 255 - (abs(dist - front) * 255) / width;
        if (bright < 0) { bright = 0; }
        led(i, (r * bright) / 255, (g * bright) / 255, (b * bright) / 255);
        i = i + 1;
    }
}

// Returns to the center, then performs successively smaller rebounds.
function effectDampedRebound(r, g, b, duration, bounces) {
    var count = getLedCount();
    if (count < 1) { return; }
    duration = _atLeastOne(duration);
    bounces = clamp(_atLeastOne(bounces), 1, 5);
    var center = (count - 1) / 2;
    var maxDist = center + 0.5;
    var progress = clamp(_frame / duration, 0, 1);
    var phase = progress * bounces * 2;
    var segment = phase - (phase % 1);
    var local = phase - segment;
    var amplitude = maxDist * (1 - progress);
    var front = segment % 2 === 0 ? amplitude * (1 - local) : amplitude * local;
    var width = 1.5 + amplitude / 8;
    var i = 0;
    while (i < count) {
        var dist = abs(i - center);
        var bright = 255 - (abs(dist - front) * 255) / width;
        if (bright < 0) { bright = 0; }
        led(i, (r * bright) / 255, (g * bright) / 255, (b * bright) / 255);
        i = i + 1;
    }
}

// Two mirrored strands grow from the center and retain a dim trailing filament.
function effectTendril(r, g, b, duration, width) {
    var count = getLedCount();
    if (count < 1) { return; }
    duration = _atLeastOne(duration);
    width = _atLeastOne(width);
    var center = (count - 1) / 2;
    var maxDist = center + 0.5;
    var progress = clamp(_frame / duration, 0, 1);
    var front = progress * maxDist;
    var i = 0;
    while (i < count) {
        var dist = abs(i - center);
        var bright = 0;
        if (dist <= front) {
            bright = 24 + 231 - ((front - dist) * 231) / width;
            if (bright < 24) { bright = 24; }
        }
        led(i, (r * bright) / 255, (g * bright) / 255, (b * bright) / 255);
        i = i + 1;
    }
}

// Deterministic drifting highlights for bubble-like accents.
function effectBubble(r, g, b, duration, bubbleCount) {
    var count = getLedCount();
    if (count < 1) { return; }
    duration = _atLeastOne(duration);
    bubbleCount = clamp(_atLeastOne(bubbleCount), 1, 8);
    var progress = clamp(_frame / duration, 0, 1);
    var j = 0;
    while (j < bubbleCount) {
        var rawPos = (j * 7 + progress * (j + 2) * count * 0.35) % count;
        var pos = rawPos - (rawPos % 1);
        led(pos, r, g, b);
        if (pos + 1 < count) { led(pos + 1, r / 4, g / 4, b / 4); }
        j = j + 1;
    }
}

// Global breathing envelope for calm, atmospheric, or idle scenes.
function effectBreathe(r, g, b, speed) {
    speed = _atLeastOne(speed);
    var phase = _positiveMod(_frame * speed * 3, 256);
    var bright = 28 + ((sin255(phase) + 255) * 227) / 510;
    fill((r * bright) / 255, (g * bright) / 255, (b * bright) / 255);
}

// One-shot fade. Positive direction fades in; negative direction fades out.
function effectFade(r, g, b, duration, direction) {
    duration = _atLeastOne(duration);
    var progress = clamp(_frame / duration, 0, 1);
    if (direction < 0) { progress = 1 - progress; }
    fill(r * progress, g * progress, b * progress);
}

// Directional comet with an explicit logical-path direction.
function effectDirectionalTrail(r, g, b, tailLen, speed, direction) {
    var count = getLedCount();
    if (count < 1) { return; }
    speed = _atLeastOne(speed);
    tailLen = _atLeastOne(tailLen) + 1;
    var pos = _phasePosition(speed, count);
    if (direction < 0) { pos = count - 1 - pos; }
    var i = 0;
    while (i < count) {
        var dist = direction < 0 ? i - pos : pos - i;
        if (dist < 0) { dist = dist + count; }
        if (dist <= tailLen + 1) {
            var bright = 255 - (dist * 255) / (tailLen + 1);
            bright = (bright * bright) / 255;
            led(i, (r * bright) / 255, (g * bright) / 255, (b * bright) / 255);
        }
        i = i + 1;
    }
}

// One-shot fill from either logical-path endpoint.
function effectDirectionalWipe(r, g, b, duration, direction) {
    var count = getLedCount();
    if (count < 1) { return; }
    duration = _atLeastOne(duration);
    var progress = clamp(_frame / duration, 0, 1);
    var boundary = progress * count;
    var i = 0;
    while (i < count) {
        var active = direction < 0 ? i >= count - boundary : i < boundary;
        if (active) { led(i, r, g, b); }
        i = i + 1;
    }
}

// A center-distance strand whose front can grow outward or retract inward.
function effectDirectionalTendril(r, g, b, duration, width, direction) {
    var count = getLedCount();
    if (count < 1) { return; }
    duration = _atLeastOne(duration);
    width = _atLeastOne(width);
    var center = (count - 1) / 2;
    var maxDist = center + 0.5;
    var progress = clamp(_frame / duration, 0, 1);
    var front = direction < 0 ? (1 - progress) * maxDist : progress * maxDist;
    var i = 0;
    while (i < count) {
        var dist = abs(i - center);
        var bright = 0;
        if (dist <= front) {
            bright = 24 + 231 - (abs(front - dist) * 231) / width;
            if (bright < 24) { bright = 24; }
        }
        led(i, (r * bright) / 255, (g * bright) / 255, (b * bright) / 255);
        i = i + 1;
    }
}

// --- Multi-dot chase ---
// numDots dots evenly spaced, chasing along the strip
// 中文：多光点追逐，多个光点等间距绕灯带前进
function effectMultiChase(r, g, b, numDots, speed) {
    var count = getLedCount();
    if (count < 1) { return; }
    numDots = _atLeastOne(numDots);
    speed = _atLeastOne(speed);
    var spacing = count / numDots;
    if (spacing < 1) { spacing = 1; }
    var offset = _phasePosition(speed, count);
    var i = 0;
    while (i < count) {
        var bright = 0;
        var d = 0;
        while (d < numDots) {
            var pos = _positiveMod(offset + d * spacing, count);
